/**
 * BACKLOG-3968 U2 — the Checklist tab with texts, through the REAL hook,
 * service and bridge shape (window.api is the shared jest mock, tests/setup.js).
 *
 * Checklist data: the producer-written fixture (checklistFixtures-3476.json,
 * regenerated by the real writer under Electron); its second checklist's second
 * item holds a text group of `m-1`. Text reader rows: fixtures/textPage-3968.json
 * (captured from the real reader).
 *
 * Proves the mount: ChecklistItemRow's Link… -> ChecklistLinkPicker (Texts tab)
 * -> useTransactionChecklist.linkTexts -> checklistService.linkText ->
 * checklists:add-link { kind: "text", targetIds: [messages.id] }; and the chip:
 * name looked up, View opens the conversation.
 */
import React from "react";
import { act, fireEvent, render, screen, waitFor, within } from "@testing-library/react";
import "@testing-library/jest-dom";
import { TransactionChecklistTab } from "../TransactionChecklistTab";
import { useTransactionChecklist } from "../../../hooks/useTransactionChecklist";
import { envelopeOf, fixtureAttachments, fixtureChecklist, fixtureEmailCommunications } from "./checklistFixture";
import captured from "./fixtures/textPage-3968.json";

jest.mock("../../modals/AttachmentPreviewModal", () => ({ AttachmentPreviewModal: () => null }));
jest.mock("../../modals/EmailThreadViewModal", () => ({ EmailThreadViewModal: () => null }));
jest.mock("../../modals/ConversationViewModal", () => ({
  ConversationViewModal: ({ messages, contactName }: { messages: Array<{ id: string }>; contactName?: string }) => (
    <div data-testid="conversation-modal" data-name={contactName}>
      {messages.map((m) => m.id).join(",")}
    </div>
  ),
}));
jest.mock("../../../../../contexts/AuthContext", () => ({
  useAuth: () => ({ currentUser: { id: "user-3476", email: "agent@example.test" } }),
}));

const checklists = () => window.api.checklists as unknown as Record<string, jest.Mock>;
const transactions = () => window.api.transactions as unknown as Record<string, jest.Mock>;
const contacts = () => window.api.contacts as unknown as Record<string, jest.Mock>;

const second = fixtureChecklist(1);
const textItem = second.items[1];
const textLink = second.linksByItemId[textItem.id][0];
const otherItem = second.items[0];
const ROW = captured.rows[0];

function Harness() {
  const checklist = useTransactionChecklist(second.checklist.transactionId);
  return (
    <TransactionChecklistTab
      checklist={checklist}
      gate="allowed"
      attachments={fixtureAttachments()}
      attachmentsLoading={false}
      emailCommunications={fixtureEmailCommunications()}
      ensureEmailsLoaded={() => Promise.resolve()}
      onRefreshLinkTargets={jest.fn()}
      onShowSuccess={jest.fn()}
      onShowError={jest.fn()}
    />
  );
}

beforeEach(() => {
  jest.clearAllMocks();
  checklists().get.mockResolvedValue({ success: true, checklists: envelopeOf([second]) });
  checklists().listTemplates.mockResolvedValue({ success: true, templates: [], source: "live" });
  checklists().addLink.mockResolvedValue({ success: true, result: { status: "added", linkId: "l-new", memberCount: 1 } });
  transactions().getTextThreads.mockResolvedValue({ success: true, threads: [captured.thread] });
  transactions().getTextThreadPage.mockResolvedValue({ success: true, rows: captured.rows, nextCursor: null });
  transactions().findTextThread.mockResolvedValue({ success: true, threadKey: captured.thread.threadId });
  contacts().resolveHandles.mockResolvedValue({ success: true, names: { [ROW.sender]: "Probe Buyer" } });
});

it("precondition: the fixture's text group is m-1, on this deal", () => {
  expect(textLink.kind).toBe("text");
  expect(textLink.members[0].messageId).toBe("m-1");
  expect(second.checklist.transactionId).toBe("txn-1");
});

it("Link… on an item opens the picker with a Texts tab, and picking a text writes kind text with its messages.id", async () => {
  render(<Harness />);
  fireEvent.click(await screen.findByTestId(`checklist-open-picker-${otherItem.id}`));
  fireEvent.click(await screen.findByTestId("checklist-picker-tab-texts"));
  fireEvent.click(await screen.findByTestId(`checklist-picker-text-${ROW.id}`));
  await act(async () => {
    fireEvent.click(screen.getByTestId("checklist-picker-link"));
  });
  expect(transactions().getTextThreads).toHaveBeenCalledWith("txn-1", null);
  expect(transactions().getTextThreadPage.mock.calls.every((c) => c[0] === "txn-1")).toBe(true);
  expect(checklists().addLink).toHaveBeenCalledTimes(1);
  expect(checklists().addLink).toHaveBeenCalledWith({ itemId: otherItem.id, kind: "text", targetIds: [ROW.id] });
});

it("a text chip names the contact (Text · <name>) and its View opens the conversation", async () => {
  render(<Harness />);
  const chip = await screen.findByTestId(`checklist-link-${textLink.id}`);
  expect(await within(chip).findByText("Text · Probe Buyer")).toBeInTheDocument();
  expect(transactions().findTextThread).toHaveBeenCalledWith("txn-1", "m-1");
  fireEvent.click(within(chip).getByTestId("checklist-link-view"));
  const modal = await screen.findByTestId("conversation-modal");
  await waitFor(() => expect(modal).toHaveTextContent(captured.rows.map((r) => r.id).join(",")));
  await waitFor(() => expect(modal).toHaveAttribute("data-name", "Probe Buyer"));
  const pageCall = transactions().getTextThreadPage.mock.calls.at(-1)!;
  expect(pageCall[0]).toBe("txn-1");
  expect(pageCall[1]).toEqual([captured.thread.threadId]);
});
